create extension if not exists pgcrypto;
create type lead_status as enum ('New','Researching','Ready to contact','Contacted','Replied','Interested','Demo','Won','Lost');
create table if not exists settings (id uuid primary key default gen_random_uuid(), kind text not null unique, payload jsonb not null default '{}', created_at timestamptz default now(), updated_at timestamptz default now());
create table if not exists instagram_connections (id uuid primary key default gen_random_uuid(), instagram_user_id text, username text, profile jsonb, access_token text, token_expires_at timestamptz, scopes text[], last_error text, created_at timestamptz default now(), updated_at timestamptz default now());
create table if not exists leads (id uuid primary key default gen_random_uuid(), business_name text, instagram_username text not null, instagram_url text, website text, category text, description text, bio text, notes text, products_services text, customer_contact_method text, relevance_summary text, research_summary text, known_facts jsonb default '[]', ai_inferences jsonb default '[]', status lead_status not null default 'New', instagram_conversation_id text, last_contacted_at timestamptz, next_followup_at timestamptz, created_at timestamptz default now(), updated_at timestamptz default now());
create table if not exists lead_activities (id uuid primary key default gen_random_uuid(), lead_id uuid references leads(id) on delete cascade, type text not null, content text, metadata jsonb default '{}', created_at timestamptz default now());
create table if not exists conversations (id uuid primary key default gen_random_uuid(), lead_id uuid references leads(id) on delete cascade, instagram_conversation_id text unique, status text, last_synced_at timestamptz, created_at timestamptz default now());
create table if not exists messages (id uuid primary key default gen_random_uuid(), conversation_id uuid references conversations(id) on delete cascade, direction text not null, body text not null, instagram_message_id text unique, sent_at timestamptz default now());
create table if not exists followups (id uuid primary key default gen_random_uuid(), lead_id uuid references leads(id) on delete cascade, due_at timestamptz not null, status text not null default 'open', previous_message text, completed_at timestamptz, created_at timestamptz default now());
create unique index if not exists leads_instagram_username_unique on leads (lower(instagram_username));
